package request

// DTO для запроса на вход
// POST /auth/login
// SSO/OAuth обычно не требует пароля, но для локальной аутентификации можно добавить

type LoginRequest struct {
	Email    string `json:"email" binding:"required,email"`
	Password string `json:"password" binding:"required"`
}

// DTO для запроса на регистрацию
// POST /auth/register

type RegisterRequest struct {
	Email      string `json:"email" binding:"required,email"`
	Password   string `json:"password" binding:"required"`
	FirstName  string `json:"first_name" binding:"required"`
	LastName   string `json:"last_name" binding:"required"`
	Profession string `json:"profession"`
}

// DTO для запроса на TOTP
// POST /auth/totp

type TOTPRequest struct {
	Code string `json:"code" binding:"required"`
}

// DTO для запроса на OAuth
// POST /auth/oauth

type OAuthRequest struct {
	Provider string `json:"provider" binding:"required"`
	Code     string `json:"code" binding:"required"`
}

package request

// DTO для создания команды
// POST /team

type TeamCreateRequest struct {
	ID          string `json:"id" binding:"required"`
	Name        string `json:"name" binding:"required"`
	Description string `json:"description"`
}

// DTO для обновления команды
// PATCH /team/:id

type TeamUpdateRequest struct {
	ID          string  `json:"id" binding:"required"`
	Name        *string `json:"name"`
	Description *string `json:"description"`
}

package request

// DTO для создания команды
// POST /team

type TeamCreateRequest struct {
	ID          string `json:"id" binding:"required"`
	Name        string `json:"name" binding:"required"`
	Description string `json:"description"`
}

// DTO для обновления команды
// PATCH /team/:id

type TeamUpdateRequest struct {
	ID          string  `json:"id" binding:"required"`
	Name        *string `json:"name"`
	Description *string `json:"description"`
}

// DTO для удаления команды
// DELETE /team/:id

type DeleteTeamRequest struct {
	ID string `json:"id" binding:"required"`
}

package response

// DTO для ответа при успешной аутентификации
// Например, после login, oauth, totp

type AuthResponse struct {
	UserID    string `json:"user_id"`
	Email     string `json:"email"`
	Token     string `json:"token"`
	ExpiresAt string `json:"expires_at"`
}

// DTO для ответа с информацией о пользователе
// GET /auth/me

type MeResponse struct {
	UserID     string   `json:"user_id"`
	Email      string   `json:"email"`
	FirstName  string   `json:"first_name"`
	LastName   string   `json:"last_name"`
	Profession string   `json:"profession"`
	IsActive   bool     `json:"is_active"`
	Roles      []string `json:"roles"`
}

package response

// DTO для ответа с информацией о команде

type TeamResponse struct {
	ID          string                `json:"id"`
	Name        string                `json:"name"`
	Description string                `json:"description"`
	Members     []TeamMemberResponse  `json:"members"`
}

// DTO для участника команды

type TeamMemberResponse struct {
	UserID        string `json:"user_id"`
	Specialization string `json:"specialization"`
	FirstName     string `json:"first_name"`
	LastName      string `json:"last_name"`
	Email         string `json:"email"`
}

package response

// Для GET /team/all

type TeamsListResponse struct {
	Teams []TeamResponse `json:"teams"`
}

// Для GET /team/:id, POST /team, PATCH /team/:id

type TeamResponse struct {
	ID          string               `json:"id"`
	Name        string               `json:"name"`
	Description string               `json:"description"`
	Members     []TeamMemberResponse `json:"members"`
}

// Для участника команды

type TeamMemberResponse struct {
	UserID        string `json:"user_id"`
	Specialization string `json:"specialization"`
	FirstName     string `json:"first_name"`
	LastName      string `json:"last_name"`
	Email         string `json:"email"`
}

// Для DELETE /team/:id (если нужен ответ)

type TeamDeleteResponse struct {
	ID      string `json:"id"`
	Message string `json:"message"`
}
